"use client";
/* Backdrop, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Backdrop(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("backdrop"); }, []);
  return React.createElement("piix-backdrop", piixAttrs(props));
}

export default Backdrop;
